// Escolhe o pilar usado há mais tempo, o motor do Reels (Veo ou animação) e monta a pesquisa.
const marca = $('Início: produzir post').first().json;
const historico = $('Histórico da marca').all()
  .map((i) => i.json)
  .filter((r) => r && r.marca === marca.marca_id);

// Pilar: nunca usado primeiro; depois o usado há mais tempo (histórico vem do mais novo pro mais antigo)
const ultimoUso = {};
historico.forEach((r, idx) => { if (r.pilar && ultimoUso[r.pilar] === undefined) ultimoUso[r.pilar] = idx; });
const pilar = [...marca.pilares].sort((a, b) => (ultimoUso[b.nome] ?? Infinity) - (ultimoUso[a.nome] ?? Infinity))[0];

// Motor do Reels: alterna Veo e animação; respeita o teto mensal de Veo (somando todas as marcas)
let motor = 'template';
let veo_no_mes = 0;
if (marca.tipo === 'reel') {
  const inicioMes = $now.setZone(marca.geral.fuso).startOf('month');
  veo_no_mes = $('Veo usados no mês').all()
    .map((i) => i.json)
    .filter((r) => r && r.motor === 'veo' && r.createdAt && DateTime.fromISO(String(r.createdAt)) >= inicioMes)
    .length;
  const ultimoReel = historico.find((r) => r.tipo === 'reel' && (r.motor === 'veo' || r.motor === 'animacao'));
  const preferido = ultimoReel && ultimoReel.motor === 'veo' ? 'animacao' : 'veo';
  motor = preferido === 'veo' && veo_no_mes < marca.geral.veo_limite_mes ? 'veo' : 'animacao';
}

// Radar da semana (workflow 00): inspiração de ângulo, formato e gancho. Só vale se tiver até 10 dias.
const linhaRadar = $('Briefing do radar (semana)').first()?.json || {};
let briefing = null;
try { briefing = linhaRadar.briefing ? JSON.parse(linhaRadar.briefing) : null; } catch (e) { briefing = null; }
const idade = linhaRadar.createdAt ? $now.diff(DateTime.fromISO(String(linhaRadar.createdAt)), 'days').days : 0;
let radar = '(sem radar recente para esta marca)';
if (briefing && idade <= 10) {
  const ideias = briefing.ideias || [];
  const doTipo = ideias.filter((i) => i.formato === (marca.tipo === 'carrossel' ? 'carrossel' : marca.tipo === 'reel' ? 'reel' : 'feed'));
  const lista = (doTipo.length ? doTipo : ideias).slice(0, 5);
  radar = [
    `Resumo: ${briefing.resumo || ''}`,
    (briefing.padroes || []).length ? `Padrões: ${(briefing.padroes || []).slice(0, 4).map((p) => `${p.padrao} (${p.por_que_funciona})`).join('; ')}` : '',
    (briefing.ganchos || []).length ? `Estruturas de gancho: ${(briefing.ganchos || []).slice(0, 4).join(' | ')}` : '',
    (briefing.lacunas || []).length ? `Lacunas do mercado: ${(briefing.lacunas || []).slice(0, 4).join('; ')}` : '',
    lista.length ? `Ideias: ${lista.map((i) => `[${i.formato}/${i.modelo}] ${i.titulo} (${i.angulo})`).join(' | ')}` : '',
  ].filter(Boolean).join('\n');
}

const recentes = historico.filter((r) => r.tema).slice(0, 20)
  .map((r) => `- [${r.tipo || 'feed'}${r.modelo ? '/' + r.modelo : ''}] ${r.tema} (${r.status})`);

return [{
  json: {
    marca,
    tipo: marca.tipo,
    motor,
    veo_no_mes,
    pilar: pilar.nome,
    consulta: pilar.consulta,
    radar,
    temas_recentes: recentes.length ? recentes.join('\n') : '(nenhum post anterior)',
  },
}];

// Junta o contexto da marca com as referências encontradas.
const ctx = $('Escolher pilar e pesquisa').first().json;
// Resposta do Gemini com busca no Google: resumo + fontes citadas (groundingChunks) + trechos ligados a cada fonte (groundingSupports).
const resposta = $input.first().json || {};
const cand = (resposta.candidates || [])[0] || {};
const meta = cand.groundingMetadata || {};
const resumo = ((cand.content || {}).parts || []).map((p) => p.text || '').join('\n').replace(/\s+/g, ' ').trim();
const chunks = (meta.groundingChunks || []).map((c) => c.web || {});
const trechos = chunks.map(() => []);
for (const s of (meta.groundingSupports || [])) {
  for (const i of (s.groundingChunkIndices || [])) if (trechos[i] && s.segment && s.segment.text) trechos[i].push(s.segment.text);
}
const resultados = chunks.map((c, i) => ({ title: c.title, url: c.uri, date: '', snippet: trechos[i].join(' ') || (i === 0 ? resumo : '') })).filter((r) => r.url);
if (!resultados.length && resumo) resultados.push({ title: 'Resumo da busca (sem fontes citadas)', url: '', date: '', snippet: resumo });

const vistos = new Set();
const fontes = resultados
  .filter((r) => r && r.title && (r.url || r.snippet))
  .filter((r) => {
    if (vistos.has(r.url)) return false;
    vistos.add(r.url);
    // Não usar o próprio site da marca como "referência externa" (o título da fonte do Google é o domínio)
    return !String(r.title).includes(ctx.marca.site);
  })
  .slice(0, 8)
  .map((r, i) => ({
    n: i + 1,
    titulo: r.title,
    url: r.url,
    data: r.date || r.last_updated || '',
    trecho: String(r.snippet || '').replace(/\s+/g, ' ').slice(0, 900),
  }));

const fontesTexto = fontes.length
  ? fontes.map((f) => `[${f.n}] ${f.titulo} (${f.data || 'sem data'})\n${f.url}\n${f.trecho}`).join('\n\n')
  : 'NENHUMA FONTE ENCONTRADA. Faça um post atemporal usando só os FATOS DA MARCA, sem números ou dados de mercado.';

const m = ctx.marca;
const guia = [
  `MARCA: ${m.nome} (${m.site}) ${m.instagram}`,
  `SEGMENTO: ${m.segmento}`,
  `PÚBLICO: ${m.publico}`,
  `POSICIONAMENTO: ${m.posicionamento}`,
  `PERSONALIDADE: ${m.personalidade}`,
  `TOM DE VOZ:\n- ${m.voz.join('\n- ')}`,
  `ASSIM SIM:\n- ${m.assim_sim.join('\n- ')}`,
  `ASSIM NÃO:\n- ${m.assim_nao.join('\n- ')}`,
  `TAGLINES OFICIAIS:\n- ${m.taglines.join('\n- ')}`,
  `FATOS DA MARCA (única fonte permitida sobre o produto, preços e prazos):\n- ${m.fatos.join('\n- ')}`,
  `CTAs PERMITIDOS:\n- ${m.ctas.join('\n- ')}`,
  `HASHTAGS BASE: ${m.hashtags_base.join(' ')}`,
  `VISUAL: ${m.visual.conceito}\nPaleta: ${m.visual.paleta}\nDireção de imagem: ${m.visual.direcao}\nProibido na imagem: ${m.visual.proibido}`,
].join('\n\n');

// Instruções de formato conforme o tipo de peça
let instrucoes;
if (ctx.tipo === 'feed') {
  instrucoes = [
    'FORMATO: post de feed (imagem única 1080x1350) montado no TEMPLATE da marca. Preencha "modelo" e "arte".',
    'Modelos: "titulo" (uma frase forte); "lista" (3 a 5 itens); "numero" (SÓ se houver um número nas referências ou nos fatos da marca); "foto" (quando uma cena real ajuda a contar; gera imagem com IA, use em no máximo 1 de cada 3 posts, veja os temas recentes).',
    'arte.etiqueta: até 3 palavras. arte.titulo: até 9 palavras; marque no máximo UMA palavra-chave entre chaves, ex.: "Cliente que espera {esfria}". arte.apoio: até 22 palavras (opcional em lista/numero).',
    'arte.itens (lista): cada item com "titulo" de até 6 palavras e "detalhe" de até 10 palavras. arte.numero: exatamente como aparece na fonte (ex.: "78%", "R$ 0,00"). arte.legenda: a frase que explica o número. arte.fonte: nome curto da fonte do número.',
    'arte.cta: curto, até 5 palavras, tirado dos CTAs permitidos.',
    'prompt_imagem (só no modelo foto): cena fotográfica SEM nenhum texto, letra ou logotipo, seguindo a direção de imagem da marca. A arte final é montada pelo template.',
  ].join('\n');
} else if (ctx.motor === 'veo') {
  instrucoes = [
    'FORMATO: Reels de ~11 segundos. Um clipe de 8 segundos gerado pelo Veo, com legendas da marca por cima, e um cartão final com logo e CTA.',
    'cenas: exatamente 2 cenas; "texto" de até 7 palavras cada (legenda sobre o vídeo). A primeira é o gancho.',
    'prompt_veo: em INGLÊS, uma cena contínua de 8 segundos, vertical 9:16, seguindo a direção de imagem da marca: ambiente, ação, enquadramento, movimento de câmera, luz e som ambiente. Sem texto, letreiros legíveis, logotipos ou pessoas olhando para a câmera.',
    'cta_video: até 5 palavras, tirado dos CTAs permitidos.',
  ].join('\n');
} else {
  instrucoes = [
    'FORMATO: Reels animado de 10 a 15 segundos, só com a tipografia e os grafismos da marca (motion graphics).',
    'cenas: 3 ou 4 cenas. "texto" de até 8 palavras e NO MÁXIMO 50 caracteres; a primeira é o gancho com até 6 palavras. Marque no máximo uma palavra por cena entre chaves para destaque. "apoio" opcional, até 14 palavras e NO MÁXIMO 80 caracteres. "etiqueta" opcional, até 3 palavras e NO MÁXIMO 24 caracteres. Texto acima do limite é recusado pelo render.',
    'cta_video: até 5 palavras e NO MÁXIMO 24 caracteres, tirado dos CTAs permitidos.',
  ].join('\n');
}

return [{
  json: {
    ...ctx,
    instrucoes_formato: instrucoes,
    fontes,
    fontes_texto: fontesTexto,
    guia_marca: guia,
    sem_fontes: fontes.length === 0,
  },
}];

