// Pega a versão aprovada (1ª ou reescrita) e monta os dados para o renderizador da marca.
const reescrito = $('Reescrever com a revisão').isExecuted;
const post = reescrito ? $('Reescrever com a revisão').first().json.output : $('Redator da marca').first().json.output;
const revisao = reescrito ? $('Revisor final').first().json.output : $('Revisor editorial').first().json.output;
const ctx = $('Montar instruções de feed e carrossel').first().json;
const m = ctx.marca;

const hashtags = [...new Set((post.hashtags || []).map((h) => (String(h).startsWith('#') ? h : '#' + h)))].slice(0, 6);
const legendaFinal = `${post.legenda.trim()}\n\n${hashtags.join(' ')}`;

let modelo = null, dados_render, rota = 'feed-template', prompt_imagem = '', prompt_veo = '';
if (ctx.tipo === 'feed' || ctx.tipo === 'carrossel') {
  // o render valida o resto (campos, tamanhos, ícones); aqui só garante que o modelo existe no catálogo da marca
  if (!(ctx.modelos_validos || []).includes(post.modelo)) throw new Error(`Modelo "${post.modelo}" não existe no catálogo de ${m.marca_id}. Válidos: ${(ctx.modelos_validos || []).join(', ')}`);
  modelo = post.modelo;
  dados_render = { marca: m.marca_id, modelo, textos: post.textos || {} };
  if (ctx.tipo === 'carrossel') rota = 'carrossel';
} else {
  dados_render = { marca: m.marca_id, cenas: (post.cenas || []).slice(0, ctx.motor === 'veo' ? 2 : 4), cta: post.cta_video || '' };
  rota = ctx.motor === 'veo' ? 'reel-veo' : 'reel-animacao';
  if (ctx.motor === 'veo') {
    prompt_veo = `${post.prompt_veo}\nStyle notes: ${m.visual.direcao}\nAvoid: ${m.visual.proibido}\nNo on-screen text, no logos.`;
  }
}

const agora = $now.setZone(m.geral.fuso);
const ext = ctx.tipo === 'reel' ? 'mp4' : 'jpg';
// carrossel: `arquivo` é só o prefixo; cada lâmina vira `${arquivo}-NN.jpg` no workflow 03
const arquivo = ctx.tipo === 'carrossel' ? `${m.marca_id}-carrossel-${agora.toFormat('yyyyLLdd-HHmmss')}` : `${m.marca_id}-${ctx.tipo}-${agora.toFormat('yyyyLLdd-HHmmss')}.${ext}`;

return [{
  json: {
    marca: m,
    tipo: ctx.tipo,
    motor: ctx.tipo === 'reel' ? ctx.motor : ('template'),
    rota,
    modelo,
    pilar: ctx.pilar,
    tema: post.tema,
    legenda: legendaFinal,
    alt_text: post.alt_text,
    dados_render,
    dados_render_json: JSON.stringify(dados_render),
    prompt_imagem: prompt_imagem.slice(0, 3800),
    prompt_veo: prompt_veo.slice(0, 3800),
    cenas_texto: (dados_render.cenas || []).map((c, i) => `${i + 1}. ${c.texto}${c.apoio ? ' — ' + c.apoio : ''}`).join('\n'),
    fontes_usadas: (post.fontes_usadas || []).join('\n'),
    nota_revisao: revisao.nota,
    observacoes_revisao: (revisao.problemas || []).join('; '),
    reescrito,
    veo_no_mes: $('Escolher pilar e pesquisa').first().json.veo_no_mes,
    arquivo,
    pasta: `instagram/${m.marca_id}`,
    midia_url: ctx.tipo === 'carrossel' ? '' : `${m.geral.url_publica_base}/instagram/${m.marca_id}/${arquivo}`,
  },
}];

// A revisão automática reprovou a 2ª versão: monta o registro e segue para o workflow 05.
const ctx = $('Montar instruções de feed e carrossel').first().json;
const post = $('Reescrever com a revisão').first().json.output;
const rev = $('Revisor final').first().json.output;
return [{ json: {
  marca: ctx.marca.marca_id, nome_marca: ctx.marca.nome, telegram_chat_id: ctx.marca.geral.telegram_chat_id,
  tipo: ctx.tipo, modelo: '', motor: 'nenhum', pilar: ctx.pilar, tema: post.tema, legenda: post.legenda, midia_url: '',
  nota_revisao: Number(rev.nota) || 0, status: 'reprovado_ia',
  erro: String('Revisão automática reprovou duas vezes: ' + (rev.problemas || []).join('; ')).slice(0, 1000),
} }];

// Monta as instruções de formato do FEED a partir do catálogo real do serviço de render.
// Para Reels, mantém as instruções que vieram de "Organizar fontes". Carrossel usa o catálogo de modelos de várias imagens.
const ctx = $('Organizar fontes').first().json;
if (ctx.tipo !== 'feed' && ctx.tipo !== 'carrossel') return [{ json: { ...ctx, modelos_validos: [] } }];

const cat = ($input.first().json || {})[ctx.marca.marca_id] || {};
const nomes = Object.keys(cat);
if (!nomes.length) throw new Error('O render não devolveu modelos de ' + ctx.tipo + ' para ' + ctx.marca.marca_id + '. Confira render_url e a credencial do render em "Marcas e regras".');

const campo = (n, d) => {
  const obrig = d.obrigatorio ? '*' : '';
  if (d.tipo === 'texto') return `${n}${obrig} (texto, máx ${d.max} caracteres${d.dica ? '; ' + d.dica : ''})`;
  if (d.tipo === 'icone') return `${n}${obrig} (um de: ${d.enum.join(' | ')})`;
  if (d.tipo === 'itens') return `${n}${obrig} (lista de ${d.min} a ${d.max} itens {icone, texto máx ${d.texto.max}})`;
  if (d.tipo === 'sinais') return `${n}${obrig} (lista de ${d.min} itens {icone, titulo máx ${d.titulo.max}, apoio máx ${d.apoio.max}})`;
  if (d.tipo === 'lista') return `${n}${obrig} (lista de ${d.min} a ${d.max} itens {${Object.entries(d.campos).map(([k, v]) => campo(k, v)).join(', ')}})`;
  if (d.tipo === 'objeto') return `${n} (objeto {${Object.entries(d.campos).map(([k, v]) => campo(k, v)).join(', ')}})`;
  return n;
};
const linhas = nomes.map((nome) => `- "${nome}": ${cat[nome].descricao}\n    campos: ${Object.entries(cat[nome].campos).map(([k, v]) => campo(k, v)).join('; ')}`);

const abertura = ctx.tipo === 'carrossel'
  ? 'FORMATO: CARROSSEL de Instagram (várias lâminas 1080x1350 que a pessoa desliza), montado no TEMPLATE da marca. A lâmina 1 é o gancho (promessa clara, sem explicar tudo); cada lâmina seguinte traz UMA ideia; a última chama para a ação (CTA permitido). Escolha UM modelo do catálogo abaixo e preencha "modelo" (nome exato) e "textos" (objeto só com os campos desse modelo). Campo com * é obrigatório.'
  : 'FORMATO: post de feed (imagem única 1080x1350) montado no TEMPLATE da marca. Escolha UM modelo do catálogo abaixo e preencha "modelo" (nome exato) e "textos" (objeto só com os campos desse modelo). Campo com * é obrigatório.';
const instrucoes = [
  abertura,
  'CATÁLOGO DE MODELOS DA MARCA:',
  linhas.join('\n'),
  'REGRAS DA ARTE',
  '- Respeite os limites de caracteres: texto maior que o limite é recusado e a peça não sai. Prefira frases curtas.',
  '- Use só os campos que existem no modelo escolhido. Ícone: só os da lista, escolhendo o que acompanha a informação.',
  '- Destaque de palavra com {chaves} só quando a descrição do modelo disser que aceita.',
  '- Número ou percentual só se estiver nas referências ou nos FATOS DA MARCA. Modelos de exemplo (antes/depois, tela) são exemplos: não afirme que é resultado real de cliente.',
