// Volta a 1 item só: as URLs públicas das lâminas, na ordem. A 1ª lâmina é a "capa" (midia_url).
const p = $('Consolidar post aprovado').first().json;
const lam = $('Separar lâminas').all().map((i) => i.json).sort((a, b) => a.ordem - b.ordem);
