// Próximo horário de postagem da marca (feed ou Reels), a partir da data planejada e nunca no passado.
const p = $('Preparar prévia').first().json;
const m = p.marca;
const dias = p.tipo === 'reel' ? [m.reel_dia] : m.dias_postagem;
const [h, min] = (p.tipo === 'reel' ? m.horario_reel : m.horario).split(':').map(Number);
const agora = $now.setZone(m.geral.fuso);

let dia = DateTime.fromISO(m.data_postagem, { zone: m.geral.fuso }).set({ hour: h, minute: min, second: 0, millisecond: 0 });
for (let i = 0; i < 21; i++) {
  if (dias.includes(dia.weekday) && dia > agora.plus({ minutes: 5 })) break;
  dia = dia.plus({ days: 1 });
}
return [{ json: { ...p, agendado_para: dia.toISO(), agendado_legivel: dia.setLocale('pt-BR').toFormat("cccc, dd/LL 'às' HH:mm") } }];

